from pycompss.api.task import task
from pycompss.api.api import compss_wait_on
from math import pi


@task(returns=tuple)
def distance_to_pi(index, value):
    """Return (index, distance from PI) for a single value."""
    return (index, abs(value - pi))

@task(returns=tuple)
def compare_distances(result1, result2):
    """Return the result with the smaller distance to PI."""
    return result1 if result1[1] < result2[1] else result2


def main(x):
    """
    Find the index of the number in the list x that is closest to PI.
    Use PyCOMPSs to compute in parallel.

    Example:

    input:  [9.18, 3.05, 7.24, 11.3, -166.49, 2.1]
    output: 5
    """
    # Launch one task per element
    futures = [distance_to_pi(i, v) for i, v in enumerate(x)]

    # Find the index with the minimum distance
    while len(futures) > 1:
        for i in range(0, len(futures), 2):
            if i + 1 < len(futures):
                futures[i // 2] = compare_distances(futures[i], futures[i + 1])
            else:
                futures[i // 2] = futures[i]  
        futures = futures[: (len(futures) + 1) // 2]

    futures = compss_wait_on(futures)

    return futures[0][0]
